int yrdawn_client_decode_WGPUCompatibilityModeLimits(const uint8_t **src, size_t *rem,
                                                     WGPUCompatibilityModeLimits *out)
{
    out->chain.next = NULL;
    if (*rem < sizeof(out->maxStorageBuffersInVertexStage)) {
        return 0;
    }
    memcpy(&out->maxStorageBuffersInVertexStage, *src, sizeof(out->maxStorageBuffersInVertexStage));
    *src += sizeof(out->maxStorageBuffersInVertexStage);
    *rem -= sizeof(out->maxStorageBuffersInVertexStage);
    if (*rem < sizeof(out->maxStorageTexturesInVertexStage)) {
        return 0;
    }
    memcpy(&out->maxStorageTexturesInVertexStage, *src,
           sizeof(out->maxStorageTexturesInVertexStage));
    *src += sizeof(out->maxStorageTexturesInVertexStage);
    *rem -= sizeof(out->maxStorageTexturesInVertexStage);
    if (*rem < sizeof(out->maxStorageBuffersInFragmentStage)) {
        return 0;
    }
    memcpy(&out->maxStorageBuffersInFragmentStage, *src,
           sizeof(out->maxStorageBuffersInFragmentStage));
    *src += sizeof(out->maxStorageBuffersInFragmentStage);
    *rem -= sizeof(out->maxStorageBuffersInFragmentStage);
    if (*rem < sizeof(out->maxStorageTexturesInFragmentStage)) {
        return 0;
    }
    memcpy(&out->maxStorageTexturesInFragmentStage, *src,
           sizeof(out->maxStorageTexturesInFragmentStage));
    *src += sizeof(out->maxStorageTexturesInFragmentStage);
    *rem -= sizeof(out->maxStorageTexturesInFragmentStage);
    return 1;
}

