struct yetty_ycore_void_result yrdawn_encode_WGPUSurfaceColorManagement(
    const WGPUSurfaceColorManagement *src, struct yetty_ycore_buffer *out)
{
    {
        struct yetty_ycore_void_result wresult =
            yetty_ycore_buffer_write(out, &src->colorSpace, sizeof(src->colorSpace));
        YETTY_RETURN_IF_ERR(yetty_ycore_void, wresult, "yrdawn_encode_WGPUSurfaceColorManagement");
    }
    {
        struct yetty_ycore_void_result wresult =
            yetty_ycore_buffer_write(out, &src->toneMappingMode, sizeof(src->toneMappingMode));
        YETTY_RETURN_IF_ERR(yetty_ycore_void, wresult, "yrdawn_encode_WGPUSurfaceColorManagement");
    }
    return YETTY_OK_VOID();
}

int yrdawn_client_decode_WGPUSurfaceColorManagement(const uint8_t **src, size_t *rem,
                                                    WGPUSurfaceColorManagement *out)
{
    out->chain.next = NULL;
    if (*rem < sizeof(out->colorSpace)) {
        return 0;
    }
    memcpy(&out->colorSpace, *src, sizeof(out->colorSpace));
    *src += sizeof(out->colorSpace);
    *rem -= sizeof(out->colorSpace);
    if (*rem < sizeof(out->toneMappingMode)) {
        return 0;
    }
    memcpy(&out->toneMappingMode, *src, sizeof(out->toneMappingMode));
    *src += sizeof(out->toneMappingMode);
    *rem -= sizeof(out->toneMappingMode);
    return 1;
}

void yrdawn_client_free_WGPUSurfaceColorManagement(WGPUSurfaceColorManagement *s)
{
    if (!s) {
        return;
    }
}

